def parse_int(key, s) do
  case str_to_int(s) do
    {:error, reason} -> {:error, reason}
    int -> {:ok, "rem(#{@prefix}#{key}, #{int}) == 0"}
  end
end

def parse_int(key, s1, s2) do
  case {str_to_int(s1), str_to_int(s2)} do
    {{:error, r1}, {:error, r2}} ->
      {:error, [r1, r2]}

    {{:error, r1}, _} ->
      {:error, r1}

    {_, {:error, r2}} ->
      {:error, r2}

    {from, int} ->
      {:ok, "rem(#{@prefix}#{key}, #{int}) == #{rem(from, int)} && #{@prefix}#{key} >= #{from}"}
  end
end

def parse_int(key, s1, s2, s) do
  case {str_to_int(s1), str_to_int(s2), str_to_int(s)} do
    {{:error, r1}, {:error, r2}, {:error, r3}} ->
      {:error, [r1, r2, r3]}

    {{:error, r1}, {:error, r2}, _} ->
      {:error, [r1, r2]}

    {{:error, r1}, _, {:error, r3}} ->
      {:error, [r1, r3]}

    {_, {:error, r2}, {:error, r3}} ->
      {:error, [r2, r3]}

    {{:error, r1}, _, _} ->
      {:error, r1}

    {_, {:error, r2}, _} ->
      {:error, r2}

    {_, _, {:error, r3}} ->
      {:error, r3}

    {from, till, int} ->
      {:ok,
       Enum.join(
         [
           "rem(#{@prefix}#{key}, #{int}) == #{rem(from, int)}",
           "#{@prefix}#{key} >= #{from}",
           "#{@prefix}#{key} <= #{till}"
         ],
         " && "
       )}
  end
end

