def add(%Slots{slots: slots}, slot, options \\ []) when is_origin(slot) do
  %Slots{slots: Group.add(slots, Slot.wrap(slot), options)}
end

def identity(%Slots{slots: slots}) do
  %Slots{slots: Group.identity(slots)}
end

def guess(input) do
  input
  |> do_guess()
  |> case do
    {:ok, nil} -> {:ok, Slot.id()}
    {:ok, origin} -> {:ok, Slot.wrap(origin)}
    {:error, reason} -> {:error, reason}
  end
end

def guess(from, to) do
  [from, to]
  |> Enum.map(&guess/1)
  |> case do
    [ok: from, ok: to] -> {:ok, Slot.join(from, to)}
    [error: from, error: to] -> {:error, {:invalid_arguments, from: from, to: to}}
    [{:error, from}, _] -> {:error, {:invalid_arguments, from: from}}
    [_, error: to] -> {:error, {:invalid_arguments, to: to}}
  end
end

def inverse(slots, options \\ [])
def inverse(%Slots.List{slots: [void()]}, _options) do
  %Slots.List{slots: []}
end
def inverse(%Slots.List{slots: []}, _options) do
  %Slots.List{slots: [void()]}
end
def inverse(%Slots.List{slots: list}, _options) do
  %Slots.List{slots: do_inverse(list, {[], nil})}
end

def inverse(slots, options \\ [])
def inverse(%Slots.Stream{slots: stream}, _options) do
  start_fun = fn -> nil end

  last_fun = fn
    nil -> {[], []}
    {dt, dt_open} -> {emit_inversed_slot({dt, dt_open}, nil), []}
  end

  after_fun = & &1

  reducer = fn
    void(), nil ->
      {:halt, :void}

    slot, nil when is_slot_open(slot) and is_nil(slot.from) ->
      {[], {slot.to, slot.to_open}}

    slot, nil ->
      {emit_inversed_slot(nil, {slot.from, slot.from_open}), {slot.to, slot.to_open}}

    slot, {dt, dt_open} ->
      {emit_inversed_slot({dt, dt_open}, {slot.from, slot.from_open}), {slot.to, slot.to_open}}
  end

  stream = Stream.transform(stream, start_fun, reducer, last_fun, after_fun)
  %Slots.Stream{slots: stream}
end

