  @global_scope |> Map.values() |> Enum.concat() |> Enum.concat([:read, :write])
end

def get_settings(_parent, _args, %{context: %{current_user: %User{role: role}}})
    when is_admin(role) do
  {:ok, Config.admin_settings()}
end
def get_settings(_parent, _args, _resolution) do
  {:error,
   dgettext("errors", "You need to be logged-in and an administrator to access admin settings")}
end

def get_application(_parent, %{client_id: client_id}, %{context: %{current_user: %User{}}}) do
  case ApplicationManager.get_application_by_client_id(client_id) do
    %Application{} = application -> {:ok, application}
    nil -> {:error, :application_not_found}
  end
end
def get_application(_parent, _args, _resolution) do
  {:error, :unauthenticated}
end

def event_categories(_parent, _args, _resolution) do
  categories =
    Categories.list()
    |> Enum.map(fn %{id: id, label: label} ->
      %{id: id |> to_string |> String.upcase(), label: label}
    end)

  {:ok, categories}
end

def feed_token_for_actor_query(actor_id) do
  from(tk in FeedToken, where: tk.actor_id == ^actor_id, preload: [:actor, :user])
end

def list_reports(
      _parent,
      %{page: page, limit: limit} = args,
      %{context: %{current_user: %User{role: role}}}
    )
    when is_moderator(role) do
  {:ok,
   Mobilizon.Reports.list_reports(
     page: page,
     limit: limit,
     sort: :updated_at,
     direction: :desc,
     status: Map.get(args, :status),
     domain: Map.get(args, :domain)
   )}
end
def list_reports(_parent, _args, _resolution) do
  {:error, dgettext("errors", "You need to be logged-in and a moderator to list reports")}
end

def get_category_statistics(_parent, _params, _context) do
  {:ok, StatisticsModule.category_statistics()}
end

def lowercase_domain(email) when is_binary(email) do
  case split_email(email) do
    [user_part, domain_part] -> {:ok, "#{user_part}@#{String.downcase(domain_part)}"}
    _ -> {:error, :invalid_email}
  end
end
def lowercase_domain(_) do
  {:error, :invalid_email}
end

def user_activity_settings(_parent, _args, %{context: %{current_user: %User{} = user}}) do
  {:ok, Users.activity_settings_for_user(user)}
end
def user_activity_settings(_parent, _args, _context) do
  {:error, :unauthenticated}
end

def cachex_spec(name, limit, default, interval, fallback \\ nil) do
  %{
    id: String.to_atom("cache_#{to_string(name)}"),
    start:
      {Cachex, :start_link,
       [
         name,
         Keyword.merge(
           cachex_options(limit, default, interval),
           fallback_options(fallback)
         )
       ]}
  }
end

