definition:
def activity_types do
  @activity_types
end

def groups_query do
  from(a in Actor, where: a.type == ^:Group, where: a.visibility == ^:public)
end

def administrator_members_for_group_query(group_id) do
  from(m in Member,
    where: m.parent_id == ^group_id and m.role in ^@administrator_roles,
    preload: [:actor]
  )
end

def group_query do
  from(a in Actor, where: a.type == ^:Group)
end

def filter_local(query) do
  from(a in query, where: is_nil(a.domain))
end

def follower_by_url(url) do
  from(f in Follower, where: f.url == ^url, preload: [:actor, :target_actor])
end

def filter_external(query) do
  from(a in query, where: not is_nil(a.domain))
end

def get_member(actor_id, parent_id) do
  case Repo.get_by(Member, actor_id: actor_id, parent_id: parent_id) do
    nil -> {:error, :member_not_found}
    member -> {:ok, member}
  end
end

def follower_by_followed_and_following_query(followed_id, follower_id) do
  from(f in Follower,
    where: f.target_actor_id == ^followed_id and f.actor_id == ^follower_id,
    preload: [:actor, :target_actor]
  )
end

def administrator_members_for_actor_query(actor_id) do
  from(m in Member,
    where: m.actor_id == ^actor_id and m.role in ^@administrator_roles,
    select: m.parent_id
  )
end

def person_query do
  from(a in Actor, where: a.type == ^:Person)
end

def members_for_actor_query(actor_id) do
  from(m in Member, where: m.actor_id == ^actor_id, preload: [:parent, :invited_by])
end

def search_addresses_query(search, limit) do
  from(a in Address, where: ilike(a.description, ^"%#{search}%"), limit: ^limit)
end

def list_action_logs_query do
  from(r in ActionLog, preload: [:actor], order_by: [desc: :id])
end

